const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centerPoint = ee.Geometry.Point([-112.246886, 34.498828]);
  const radius = 50 * 1609.34; // 50 miles to meters
  const aoi = centerPoint.buffer(radius);

  const startDate = '2017-06-20';
  const endDate = '2017-06-30';

  console.log('Searching for fires within 50 miles of (34.498828, -112.246886)');
  console.log('Date range: June 20-30, 2017');

  // 2. Data Acquisition - MODIS Thermal Anomalies/Fire
  let fireCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  const collectionSize = fireCollection.size().getInfo();
  console.log(`Fire images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try MODIS 061 version or VIIRS
    fireCollection = ee.ImageCollection('MODIS/061/MOD14A1')
      .filterDate(startDate, endDate)
      .filterBounds(aoi);

    const fallbackSize = fireCollection.size().getInfo();
    console.log(`Fallback collection size: ${fallbackSize}`);

    if (fallbackSize === 0) {
      console.log('No fire data available for this period.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Check for fire detections
  // FireMask band: 0-9 scale, values >= 7 indicate fires with varying confidence
  const fireMask = fireCollection.select('FireMask').max();

  // Count fire pixels (value >= 7 indicates fire)
  const firePixels = fireMask.gte(7);

  const stats = firePixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const fireCount = stats.FireMask;

  // Also check MaxFRP (Fire Radiative Power) for additional validation
  const maxFRP = fireCollection.select('MaxFRP').max();
  const frpStats = maxFRP.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxFirePower = frpStats.MaxFRP;

  console.log(`Fire pixels detected: ${fireCount || 0}`);
  console.log(`Max Fire Radiative Power: ${maxFirePower || 0} MW`);

  // 4. Validation & Final Answer
  if (fireCount === null && maxFirePower === null) {
    console.log('Calculation returned null values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (fireCount > 0 || maxFirePower > 0) {
    console.log('Fires were detected in the area during this period.');
    console.log('<answer>A</answer>');
  } else {
    console.log('No fires detected in the area during this period.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
